<script lang="ts">let { message,kind='info' }=$props<{message:string;kind?:'info'|'error'|'success'}>();</script><div class:danger={kind==='error'} class:success={kind==='success'} class="toast" role="status">{message}</div>
<style>.toast{position:fixed;right:24px;bottom:24px;z-index:100;max-width:420px;padding:12px 16px;background:var(--surface-1);border:1px solid var(--border);border-radius:10px;box-shadow:var(--shadow-lg);animation:toast-in .2s var(--ease)}.danger{border-color:#d8485b42;color:#a92d3e;background:#fff7f8}.success{border-color:#24845f42;color:#176747;background:#f4fbf8}@keyframes toast-in{from{opacity:0;transform:translateY(8px)}}</style>
